-- Rewrites the header added by 20260928_section_headers_zx138_zx65.sql:
-- * that run was pasted with Windows line endings, so every header line ended in \r;
-- * chunks whose text moves into a new SECTION/Group get "→ <new group>" in the title (93 chunks),
--   e.g. a chunk that starts in "Travel Device (ZX130-5G)" but holds the 138MF weight;
-- * a heading cut by the chunk boundary ("Travel Device (ZX") is no longer carried forward.
-- Built with E'...\n' strings so the result does not depend on the line endings of this file.
-- Idempotent: only rows whose first line still ends in \r are touched.
begin;
update documents set content = E'Section: WORKSHOP MANUAL - Cover & Contents\nModel: ZX65USB-5A\nKategori: WORKSHOP MANUAL\n\n' || regexp_replace(content, E'^Section:[^\n]*\n[^\n]*\n[^\n]*\n\r?\n', '') where id = 741 and content ~ E'^Section: [^\n]*\r\n';
